"""
    Helper function to determine the year ticks for a graph based on how many
    years are passed as input

    Parameters
    ----------
    years : list
        A list of the years for this dataset
    Returns
    -------
    year_ticks : list
        A list of places for tick marks on the years axis of the graph
    """
def __get_years_tickvals(years: Any) -> object {
    min_year = int(min(years));
    max_year = int(max(years));
    delta = max_year - min_year;
    if (delta >= 80) {
        stepsize = 10;
    } elif (delta >= 40) {
        stepsize = 5;
    } elif (delta >= 16) {
        stepsize = 2;
    } else {
        stepsize = 1;
    }
    year_ticks = `list(range(min_year, (max_year + stepsize), stepsize));
    return year_ticks;
}

"""Replace special characters '&', '<' and '>' by SGML entities.

    This is a slightly more efficient version of the cgi.escape by
    using 'in' membership to test if the replace is needed.

    This function returns a plain string. Programs using the HTML builder
    should call ``webhelpers.html.builder.escape()`` instead of this to prevent
    double-escaping.

    Changed in WebHelpers 1.2: escape single-quote as well as double-quote.

    """
def cgi_escape(s: Any, quote: Any = False) -> object {
    if ('&' in s) {
        s = s.replace("&", "&amp;");
    }
    if ('<' in s) {
        s = s.replace("<", "&lt;");
    }
    if ('>' in s) {
        s = s.replace(">", "&gt;");
    }
    if quote {
        s = s.replace('"', "&quot;");
        s = s.replace("'", "&apos;");
    }
    return s;
}

"""
    Lorentizian function.

    Parameters
    -------------

    t : 'array'

    pars : 'array'
        Parameters used in the decomposition. E.g. heigh, center, width.

    Returns
    -------------
    function
    """
def asym_peak_L(t: Any, pars: Any) -> object {
    a0 = pars[0];
    a1 = pars[1];
    a2 = pars[2];
    f = a0 * ((a2 ** 2) / (((t - a1) ** 2) + ((1.0 * a2) ** 2)));
    return f;
}

"""Given two strings containing paths to directories, find the
    lowest level parent directory that they share and return it's path.
    If none are found, return False"""
def find_common_directory(directory_x: Any, directory_y: Any) -> object {
    x_path = directory_x.split("\\");
    y_path = directory_y.split("\\");
    result_path = "";
    ticker = len(x_path);
    if (ticker > len(y_path)) {
        ticker = len(y_path);
    }
    for i in range(ticker) {
        if (x_path[i] == y_path[i]) {
            result_path += x_path[i] + "\\";
        } else {
            break;
        }
    }
    if (result_path == "") {
        return None;
    }
    return result_path;
}

