"""Unsanitizes a previously sanitized token."""
def unsanitize(t: Any, mappings: Any) -> object {
    final = t;
    for (original, sanitized) in mappings.items() {
        assert (len(original) == 1);
        final = final.replace(sanitized, original);
    }
    return final;
}

